// Theme palettes and colour helpers follow SlotForge Timing's App Theme settings.
function bannerText(settings){return settings.banner||{line1:'Your collection, your workshop',line2:settings.name,line3:'Keep every car organised. Preserve the parts, work and setups that make it yours.'};}
function bannerMarkup(settings){const b=bannerText(settings);return `<div class="label">${esc(b.line1)}</div><h1>${esc(b.line2)}</h1><p>${esc(b.line3)}</p>`;}
function setCustomColors(element,colors){for(const [key] of Theme.COLORS)element.style.setProperty('--'+key,colors?colors[key]:'');element.style.setProperty('--on-accent',colors?Theme.onAccent(colors.accent):'');}
function applyTheme(settings=db.settings){const root=document.documentElement;root.dataset.theme=settings.theme;const custom=settings.theme==='custom',colors=Theme.customOf(settings);setCustomColors(root,custom?colors:null);root.dataset.tone=(custom?Theme.isLight(colors.panel):['light','ocean'].includes(settings.theme))?'light':'dark';root.dataset.brandTone=(custom?Theme.ratio('#4d4d4d',colors.bg)>Theme.ratio('#f5f5f5',colors.bg):['light','ocean'].includes(settings.theme))?'light':'dark';}
function paintCustomTile(){const tile=document.querySelector('[data-theme-pick="custom"]');if(tile)setCustomColors(tile,Theme.customOf(db.settings));}
function themeOptions(selected){return Theme.THEMES.map(([key,name])=>`<option value="${key}" ${key===selected?'selected':''}>${esc(name)}</option>`).join('');}
function renderAppearance(part='all'){const theme=panel('App theme',`<p class="muted">The same colour choices as SlotForge Timing. Preferences are saved with this database.</p><div class="theme-grid" role="group" aria-label="App theme">${Theme.THEMES.map(([key,name])=>`<button type="button" class="theme-tile" data-theme="${key}" data-theme-pick="${key}" data-action="choose-theme" data-id="${key}" aria-pressed="${db.settings.theme===key}"><span class="theme-swatches" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span>${db.settings.theme===key?'✓ ':''}${esc(name)}</span></button>`).join('')}</div><div class="actions mt">${btn('Edit custom colours','custom-colors')}</div>`);const banner=panel('Welcome banner',`<p class="muted">Make the three lines on Overview your own.</p><div class="banner-preview">${bannerMarkup(db.settings)}</div><div class="actions mt">${btn('Edit banner text','edit-banner')}</div>`);const zoom=panel('Interface size',`<p class="muted">Resize text, buttons and menus together. Saved on this computer for all your collections.</p><div class="actions ui-scale-controls"><label class="field">Size<select id="ui-scale">${UiScale.levels.map(n=>`<option value="${n}" ${UiScale.current===n?'selected':''}>${n}%${n===100?' (standard)':''}</option>`).join('')}</select></label><button type="button" class="btn" id="ui-scale-reset">Reset to 100%</button></div>`);return part==='theme'?theme+zoom+renderBackgroundPreference():part==='banner'?banner:theme+zoom+renderBackgroundPreference()+banner;}
function paletteFor(key){const tile=document.querySelector('[data-theme-pick="'+key+'"]');if(!tile)return {...Theme.DEFAULT};const css=getComputedStyle(tile);return Object.fromEntries(Theme.COLORS.map(([k])=>[k,Theme.hex6(css.getPropertyValue('--'+k))||Theme.DEFAULT[k]]));}
let colorDraft=null;
function previewColors(){applyTheme({theme:'custom',customColors:colorDraft});$('#color-warning').textContent=Theme.problems(colorDraft).join(' ');}
function editColors(){const revision=db.revision;colorDraft=db.settings.customColors?Theme.customOf(db.settings):paletteFor(db.settings.theme);modal('Your own colours',`<p class="muted">Preview changes while choosing. Save applies the Custom theme; Cancel restores your saved theme.</p><div class="color-grid">${Theme.COLORS.map(([key,name,where])=>`<label class="color-row"><input type="color" name="color-${key}" data-theme-color="${key}" value="${colorDraft[key]}" aria-label="${esc(name)}"><span><strong>${esc(name)}</strong><small>${esc(where)}</small></span></label>`).join('')}</div><p id="color-warning" class="note" role="status" hidden></p><div class="row mt"><label for="theme-copy">Start from</label><select id="theme-copy">${themeOptions(db.settings.theme==='custom'?'dark':db.settings.theme).replace(/<option value="custom"[^>]*>.*?<\/option>/,'')}</select>${btn('Copy its colours','copy-theme')}</div>`,async()=>change('settings.save',{revision,theme:'custom',customColors:{...colorDraft}}));previewColors();$('#color-warning').hidden=!$('#color-warning').textContent;}
function editBanner(){const revision=db.revision,b=bannerText(db.settings);modal('Welcome banner text',`<div class="form-grid">${[['line1','Line 1 · small heading',120],['line2','Line 2 · main title',200],['line3','Line 3 · description',500]].map(([key,label,max])=>`<label class="field wide">${label}<input name="${key}" value="${esc(b[key])}" maxlength="${max}" required></label>`).join('')}</div><div class="banner-preview mt" id="banner-preview">${bannerMarkup(db.settings)}</div><div class="actions mt">${btn('Restore default text','banner-defaults')}</div><p class="tiny muted">Long text wraps to fit the window. These lines stay private to this database.</p>`,async values=>change('settings.save',{revision,banner:bannerReset?null:{line1:values.line1,line2:values.line2,line3:values.line3}}));bannerReset=false;}
let bannerReset=false;
function previewBanner(){const values=Object.fromEntries(['line1','line2','line3'].map(k=>[k,$('#dialog [name="'+k+'"]').value]));$('#banner-preview').innerHTML=bannerMarkup({banner:values});}
async function appearanceAction(action,id){switch(action){
  case 'background-mode':net=await api('network','background-mode',{enabled:!net.background?.enabled});render();return true;
  case 'choose-theme':if(id==='custom'&&!db.settings.customColors){editColors();return true;}await change('settings.save',{revision:db.revision,theme:id});render();return true;
  case 'custom-colors':editColors();return true;
  case 'copy-theme':colorDraft=paletteFor($('#theme-copy').value);for(const [k]of Theme.COLORS)$('#dialog [data-theme-color="'+k+'"]').value=colorDraft[k];previewColors();$('#color-warning').hidden=!$('#color-warning').textContent;return true;
  case 'edit-banner':editBanner();return true;
  case 'banner-defaults':{const defaults=bannerText({name:db.settings.name});for(const k of ['line1','line2','line3'])$('#dialog [name="'+k+'"]').value=defaults[k];bannerReset=true;previewBanner();return true;}
}return false;}
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.themeColor&&colorDraft){colorDraft[el.dataset.themeColor]=Theme.hex6(el.value)||colorDraft[el.dataset.themeColor];previewColors();$('#color-warning').hidden=!$('#color-warning').textContent;}if($('#banner-preview')&&['line1','line2','line3'].includes(el.name)){bannerReset=false;previewBanner();}});
document.getElementById('dialog').addEventListener('close',()=>{if(db)applyTheme();colorDraft=null;});

function renderBackgroundPreference(){const b=net.background;if(!b)return '';return panel('Keep Paddock available',`<p class="muted">Optionally keep this same Paddock process running when you close its window. Timing and Telemetry can continue using enabled connections. This does not enable LAN sharing. Compatible service clients can also start Paddock through its enabled local service registration.</p><p>${badge(b.enabled&&b.ready?'Background mode on':'Background mode off',b.enabled&&b.ready?'good':'')}</p>${b.error?`<p class="note">${esc(b.error)}</p>`:''}<div class="actions">${btn(b.enabled?'Turn background mode off':'Keep running when window closes','background-mode')}</div><p class="tiny muted">Reopen Paddock using its tray or menu-bar icon, or launch it again. Choose “Quit Paddock completely” from the icon’s menu to stop it. Timing can read and write the shared local file without Paddock running. Network and local HTTP clients, and Paddock Portal, need their Paddock service running. Your computer can still sleep.</p>`);}
